python3 - <<'PY'
import csv, datetime, statistics, math
rows=list(csv.DictReader(open("data.csv")))
def series(b):
    d={}
    for r in rows:
        if r["band"]==b:
            d[r["date"]]=float(r["y"])
    return dict(sorted(d.items()))
for b in ["VH","VV","VV-VH"]:
    s=series(b)
    vals=list(s.values())
    print(b, "mean",round(statistics.mean(vals),3),"sd",round(statistics.stdev(vals),3),
          "first",round(vals[0],2),"last",round(vals[-1],2))
    # trend
    n=len(vals); xs=list(range(n))
    mx=statistics.mean(xs); my=statistics.mean(vals)
    slope=sum((x-mx)*(y-my) for x,y in zip(xs,vals))/sum((x-mx)**2 for x in xs)
    print("  slope/step",round(slope,5),"over 220 steps",round(slope*220,2))
    # seasonal: mean by month
    bym={}
    for dt,v in s.items():
        m=dt[5:7]; bym.setdefault(m,[]).append(v)
    print("  monthly means:",{m:round(statistics.mean(v),2) for m,v in sorted(bym.items())})
