import csv, json, datetime as dt
rows=list(csv.DictReader(open("data.csv")))
hist={}
for r in rows:
    d=dt.date.fromisoformat(r["date"])
    hist.setdefault(d,{})[r["band"]]=float(r["y"])
dates=sorted(hist)
future=[(r["period_id"],dt.date.fromisoformat(r["date"])) for r in csv.DictReader(open("visits_to_predict.csv"))]
pred={}
for pid,d in future:
    # weight historical dates by proximity in day-of-year (circular), gaussian
    def doy(x): return x.timetuple().tm_yday
    dd=doy(d)
    best=None
    for hd in dates:
        diff=abs(doy(hd)-dd); diff=min(diff,366-diff)
        if best is None or diff<best[0]: best=(diff,hd)
    pred[pid]={b:round(hist[best[1]][b],6) for b in hist[best[1]]}
    print(pid,d,best[1],best[0],pred[pid])
json.dump(pred,open("all_preds.json","w"))
