steps.reply:
The series is strongly seasonal (VH swings between -22 and -14.7), so the flattened recursive SHC output is clearly wrong. A seasonal-analog forecast is more appropriate: match each target date to historical visits at the same time of year, then adjust for the parcel's recent level bias.```bash
python3 - <<'PY'
import csv, json, datetime as dt
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
d=defaultdict(dict); dates={}
for r in rows:
    d[r["period_id"]][r["band"]]=float(r["y"])
    dates[r["period_id"]]=dt.date.fromisoformat(r["date"])
hist=sorted(d)
bands=["VH","VV","VV-VH"]
targets=[(r["period_id"],dt.date.fromisoformat(r["date"])) for r in csv.DictReader(open("visits_to_predict.csv"))]

def doy(date):
    # day of year with wraparound distance
    return date.timetuple().tm_yday

def dist(a,b):
    return min(abs(a-b),366-abs(a-b))

pred={}
for pid,tdate in targets:
    td=doy(tdate)
    # analogs: historical periods within 15 days of year
    analogs=[(p,dates[p]) for p in hist if dist(doy(dates[p]),td)<=15]
    vals={b:[] for b in bands}
    for p,pd in analogs:
        for b in bands: vals[b].append(d[p][b])
    pred[pid]={b: sum(v)/len(v) for b,v in vals.items()}
    print(pid,tdate,len(analogs),{b:round(pred[pid][b],3) for b in bands})

# recent bias: last observed vs seasonal mean at last observed date
last=hist[-1]; ld=dates[last]; td=doy(ld)
an=[p for p in hist if dist(doy(dates[p]),td)<=15 and p!=last]
bias={b: d[last][b]-sum(d[p][b] for p in an)/len(an) for b in bands}
print("bias",{b:round(bias[b],3) for b in bands})
for pid in pred:
    for b in bands: pred[pid][b]+=bias[b]
json.dump(pred,open("seasonal.json","w"))
print({pid:{b:round(v,3) for b,v in pred[pid].items()} for pid in list(pred)[:3]})
PY
