import csv, datetime, json
rows=list(csv.DictReader(open("data.csv")))
def d(s): return datetime.date.fromisoformat(s)
hist={}
for r in rows:
    hist.setdefault(r["band"],[]).append((d(r["date"]), float(r["y"])))
future=[(r["period_id"], d(r["date"])) for r in csv.DictReader(open("visits_to_predict.csv"))]

preds={}
for pid,fd in future:
    p={}
    for band,series in hist.items():
        # weight by day-of-year proximity, gaussian kernel
        def doy(x): return x.timetuple().tm_yday
        fd_doy=doy(fd)
        def dist(a,b):
            dd=abs(a-b); return min(dd,366-dd)
        ws=[]
        for t,v in series:
            dd=dist(doy(t),fd_doy)
            w=2.718**(-(dd/15.0)**2)
            ws.append((w,v))
        tot=sum(w for w,_ in ws)
        if tot<1e-9:
            # nearest doy
            best=min(series,key=lambda tv:dist(doy(tv[0]),fd_doy))
            p[band]=best[1]
        else:
            p[band]=sum(w*v for w,v in ws)/tot
    preds[pid]=p
    print(pid, fd, {b:round(preds[pid][b],3) for b in sorted(p)})

json.dump({"prediction":preds}, open("clim_preds.json","w"), indent=1)
